insert into public.exercises (slug, visibility, category, level, title, content) values
  ('fg-oneassist', 'library', 'doigts', 'adv', '{"fr":"Suspension à un bras assistée","en":"Assisted one-arm hang"}'::jsonb, '{"fr":{"description":"Suspension unilatérale sur réglette 20 mm avec allègement à la poulie ou à l''élastique, pour développer la force unilatérale sans surcharge.","muscles":"Fléchisseurs des doigts en unilatéral, coiffe des rotateurs, chaîne scapulaire","cues":"Épaule engagée vers le bas et l''arrière. Le bassin reste sous la main, pas de rotation du tronc.","errors":"Laisser l''épaule remonter dans l''oreille, compenser par une rotation du corps.","dose":"5 séries de 7 s par bras, 2 min de repos. Réduire l''assistance de 2 kg toutes les 2 à 3 semaines.","contraindications":"Instabilité d''épaule, moins de 130 % du poids de corps en suspension à deux bras."},"en":{"description":"Single-arm hang on a 20 mm edge with pulley or band assistance, building unilateral strength without overload.","muscles":"Unilateral finger flexors, rotator cuff, scapular chain","cues":"Shoulder engaged down and back. Hips stay under the hand, no trunk rotation.","errors":"Letting the shoulder shrug into the ear, compensating with body rotation.","dose":"5 sets of 7 s per arm, 2 min rest. Reduce assistance by 2 kg every 2 to 3 weeks.","contraindications":"Shoulder instability, less than 130% body weight on a two-arm hang."}}'::jsonb),
  ('fg-density', 'library', 'doigts', 'inter', '{"fr":"Suspensions de densité 30 s","en":"Density hangs, 30 s"}'::jsonb, '{"fr":{"description":"Suspensions longues à charge légère sur prise confortable, pour développer la tolérance des tissus et la capacité aérobie locale.","muscles":"Tissus conjonctifs des doigts, capillarisation de l''avant-bras","cues":"Intensité volontairement basse : vous devez pouvoir tenir 40 s si nécessaire. Prise tendue de préférence.","errors":"Chercher l''échec sur ces séries. Ce n''est pas leur objet.","dose":"5 à 8 séries de 30 s, 1 min de repos. Excellent en séance de récupération active.","contraindications":"Aucune contre-indication majeure hors douleur aiguë."},"en":{"description":"Long, lightly loaded hangs on a comfortable hold to build tissue tolerance and local aerobic capacity.","muscles":"Finger connective tissue, forearm capillarisation","cues":"Deliberately low intensity: you should be able to hold 40 s if needed. Open-hand grip preferred.","errors":"Chasing failure on these sets. That is not what they are for.","dose":"5 to 8 sets of 30 s, 1 min rest. Excellent in an active recovery session.","contraindications":"No major contraindication other than acute pain."}}'::jsonb),
  ('fg-gripcompare', 'library', 'doigts', 'inter', '{"fr":"Protocole arqué / tendu comparé","en":"Crimp vs open-hand comparative protocol"}'::jsonb, '{"fr":{"description":"Mesure alternée de la charge maximale en demi-arqué puis en tendu, pour objectiver un déséquilibre de préhension.","muscles":"Fléchisseurs profonds (tendu) contre superficiels et interosseux (arqué)","cues":"Même réglette, même durée, 3 min entre les deux mesures. Notez le ratio tendu/arqué : sous 0,85, le tendu est votre point faible.","errors":"Comparer sur deux séances différentes ou deux réglettes différentes, ce qui invalide la comparaison.","dose":"1 fois toutes les 6 à 8 semaines, en début de séance, doigts frais.","contraindications":"Mêmes contre-indications que les suspensions maximales."},"en":{"description":"Alternating maximal load measurement in half-crimp then open-hand, to quantify a grip imbalance.","muscles":"Deep flexors (open-hand) versus superficial flexors and interossei (crimp)","cues":"Same edge, same duration, 3 min between measurements. Record the open/crimp ratio: below 0.85, open-hand is your weak point.","errors":"Comparing across two different sessions or two different edges, which invalidates the comparison.","dose":"Once every 6 to 8 weeks, at the start of a session, on fresh fingers.","contraindications":"Same contraindications as max hangs."}}'::jsonb),
  ('fg-pockets', 'library', 'doigts', 'adv', '{"fr":"Bi-doigts contrôlés","en":"Controlled two-finger pockets"}'::jsonb, '{"fr":{"description":"Suspensions sur bi-doigts (majeur-annulaire puis index-majeur) à charge très réduite, pour préparer les pochettes en falaise.","muscles":"Fléchisseurs isolés par doigt, poulies A2 des doigts longs","cues":"Commencez avec les pieds au sol supportant la moitié du poids. Le mono-doigt n''est jamais un exercice de base.","errors":"Passer directement au bi-doigt suspendu à poids de corps complet.","dose":"3 séries de 7 s par paire, très progressif sur 8 semaines minimum.","contraindications":"Tout antécédent de rupture de poulie, moins de 145 % du poids de corps en suspension quatre doigts."},"en":{"description":"Hangs on two-finger pockets (middle-ring then index-middle) at heavily reduced load, preparing for outdoor pockets.","muscles":"Per-finger flexors, A2 pulleys of the long fingers","cues":"Start with feet on the ground taking half your weight. One-finger hangs are never a foundational exercise.","errors":"Jumping straight to a full-bodyweight two-finger hang.","dose":"3 sets of 7 s per pair, very progressive over at least 8 weeks.","contraindications":"Any history of pulley rupture, less than 145% body weight on a four-finger hang."}}'::jsonb),
  ('fg-board', 'library', 'doigts', 'inter', '{"fr":"Cycles de pan Beastmaker","en":"Beastmaker board cycles"}'::jsonb, '{"fr":{"description":"Enchaînement structuré de préhensions variées sur poutre : arqué, tendu, bi-doigts, pinces, sur une séance de 20 minutes.","muscles":"Ensemble des préhensions, transfert vers la variété des prises réelles","cues":"Alternez les préhensions plutôt que de répéter la même. C''est la variété qui construit la robustesse.","errors":"Faire le cycle complet à intensité maximale sur chaque préhension.","dose":"1 cycle de 20 min, 1 à 2 fois par semaine, en complément et non en remplacement du bloc.","contraindications":"Douleur active sur une préhension : retirez-la du cycle, ne l''évitez pas par compensation."},"en":{"description":"Structured sequence of varied grips on a fingerboard: crimp, open-hand, two-finger, pinch, over a 20-minute session.","muscles":"Full range of grip positions, transferring to real hold variety","cues":"Alternate grips rather than repeating one. Variety is what builds robustness.","errors":"Running the full cycle at maximal intensity on every grip.","dose":"One 20-min cycle, 1 to 2 times per week, complementing rather than replacing bouldering.","contraindications":"Active pain on one grip: remove it from the cycle rather than compensating around it."}}'::jsonb),
  ('fg-nohang', 'library', 'doigts', 'all', '{"fr":"Tirage sans suspension (no-hang)","en":"No-hang lifts"}'::jsonb, '{"fr":{"description":"Tirage vertical d''une charge à l''aide d''un bloc de préhension, pieds au sol. Charge parfaitement contrôlée, aucun risque de chute.","muscles":"Fléchisseurs des doigts, sans contrainte sur l''épaule","cues":"Bras le long du corps, coude à 30° environ. Idéal pour charger les doigts quand l''épaule ou le coude est en rééducation.","errors":"Tirer avec le dos plutôt qu''avec les doigts : le bloc doit rester le maillon faible.","dose":"5 séries de 10 s, 2 min de repos. Charge ajustable au kilo près.","contraindications":"Aucune contre-indication majeure. C''est souvent la porte d''entrée la plus sûre."},"en":{"description":"Vertical lift of a load using a grip block, feet on the ground. Perfectly controlled load, no fall risk.","muscles":"Finger flexors, with no shoulder demand","cues":"Arm at your side, elbow around 30°. Ideal for loading fingers while a shoulder or elbow is rehabbing.","errors":"Pulling with the back rather than the fingers: the block must stay the weak link.","dose":"5 sets of 10 s, 2 min rest. Load adjustable to the kilo.","contraindications":"No major contraindication. Often the safest entry point."}}'::jsonb),
  ('pw-limit', 'library', 'pliometrie', 'inter', '{"fr":"Bloc limite","en":"Limit bouldering"}'::jsonb, '{"fr":{"description":"Travail de 2 à 4 blocs à votre maximum absolu, sur des mouvements que vous ne réussissez pas encore.","muscles":"Recrutement neuromusculaire maximal, coordination inter-segmentaire","cues":"3 à 5 min de repos entre chaque essai. Un essai raté par fatigue n''apprend rien : arrêtez la série.","errors":"Enchaîner les essais toutes les 30 secondes, ce qui transforme la séance en travail d''endurance.","dose":"45 à 60 min, 4 à 6 essais par bloc, 2 fois par semaine sur doigts frais.","contraindications":"Fatigue accumulée, ACWR au-dessus de 1,4, douleur active."},"en":{"description":"Working 2 to 4 problems at your absolute maximum, on moves you cannot yet do.","muscles":"Maximal neuromuscular recruitment, inter-segmental coordination","cues":"3 to 5 min rest between attempts. An attempt failed through fatigue teaches nothing: end the set.","errors":"Attempting every 30 seconds, which turns the session into endurance work.","dose":"45 to 60 min, 4 to 6 attempts per problem, twice a week on fresh fingers.","contraindications":"Accumulated fatigue, ACWR above 1.4, active pain."}}'::jsonb),
  ('pw-dropcatch', 'library', 'pliometrie', 'adv', '{"fr":"Lâcher-rattrape sur pan","en":"Drop-catch on the board"}'::jsonb, '{"fr":{"description":"Depuis une position de blocage, lâchez une main et rattrapez la même prise en contrôlant l''excentrique.","muscles":"Force excentrique des doigts et de l''épaule, raideur active de la chaîne","cues":"Amplitude de chute très courte au départ, 5 cm maximum. C''est un exercice de contrôle, pas de choc.","errors":"Chercher l''amplitude maximale dès la première séance.","dose":"3 séries de 3 par bras, 2 min de repos. Toutes les 2 semaines maximum.","contraindications":"Tout antécédent de poulie ou d''épaule non consolidé."},"en":{"description":"From a locked position, release one hand and catch the same hold, controlling the eccentric.","muscles":"Eccentric finger and shoulder strength, active stiffness of the chain","cues":"Very short drop range at first, 5 cm maximum. This is a control exercise, not an impact one.","errors":"Chasing maximum range from the first session.","dose":"3 sets of 3 per arm, 2 min rest. Every 2 weeks at most.","contraindications":"Any unconsolidated pulley or shoulder history."}}'::jsonb),
  ('pw-wpull', 'library', 'tirage', 'inter', '{"fr":"Traction lestée lourde","en":"Heavy weighted pull-up"}'::jsonb, '{"fr":{"description":"Traction complète avec charge additionnelle, sur 3 à 5 répétitions maximum.","muscles":"Grand dorsal, grand rond, biceps, fixateurs de l''omoplate","cues":"Amplitude complète : bras tendus en bas, menton franchement au-dessus de la barre. Serrez les fessiers pour éviter le cambré.","errors":"Réduire l''amplitude en bas pour ajouter du poids.","dose":"5 séries de 3 à 5 répétitions, 3 min de repos. 1 à 2 fois par semaine.","contraindications":"Tendinopathie du coude en phase douloureuse."},"en":{"description":"Full pull-up with added load, at 3 to 5 reps maximum.","muscles":"Latissimus dorsi, teres major, biceps, scapular stabilisers","cues":"Full range: straight arms at the bottom, chin clearly above the bar. Squeeze the glutes to avoid arching.","errors":"Shortening the bottom range in order to add weight.","dose":"5 sets of 3 to 5 reps, 3 min rest. 1 to 2 times per week.","contraindications":"Elbow tendinopathy in a painful phase."}}'::jsonb),
  ('pw-pogo', 'library', 'pliometrie', 'inter', '{"fr":"Pogos et impulsion de bassin","en":"Pogos and hip drive"}'::jsonb, '{"fr":{"description":"Balancements rythmés du bassin sur un pan surplombant pour générer l''élan d''un mouvement sans tirer des bras.","muscles":"Fléchisseurs de hanche, abdominaux profonds, coordination","cues":"Le pied libre lance, le bassin suit, la main part au dernier moment.","errors":"Utiliser les bras pour lancer, ce qui annule tout le bénéfice.","dose":"6 à 10 séquences par côté, en fin d''échauffement.","contraindications":"Douleur lombaire en extension."},"en":{"description":"Rhythmic hip swings on a steep board to generate momentum for a move without pulling with the arms.","muscles":"Hip flexors, deep abdominals, coordination","cues":"The free foot swings, the hips follow, the hand leaves last.","errors":"Using the arms to generate the swing, which defeats the purpose.","dose":"6 to 10 sequences per side, at the end of the warm-up.","contraindications":"Lumbar pain in extension."}}'::jsonb),
  ('en-intervals', 'library', 'endurance', 'inter', '{"fr":"Intervalles bloc 30/30","en":"Boulder intervals 30/30"}'::jsonb, '{"fr":{"description":"30 secondes de grimpe continue, 30 secondes de repos, répété 10 à 16 fois sur un pan.","muscles":"Puissance aérobie locale, resynthèse rapide de la phosphocréatine","cues":"Intensité stable du premier au dernier intervalle. Chronométrez, ne comptez pas les mouvements.","errors":"Partir trop fort et s''effondrer au huitième intervalle.","dose":"2 séries de 8 intervalles, 5 min entre les séries.","contraindications":"Douleur de coude, phase de récupération."},"en":{"description":"30 seconds of continuous climbing, 30 seconds of rest, repeated 10 to 16 times on a board.","muscles":"Local aerobic power, rapid phosphocreatine resynthesis","cues":"Steady intensity from first to last interval. Use a timer, do not count moves.","errors":"Going out too hard and falling apart by the eighth interval.","dose":"2 sets of 8 intervals, 5 min between sets.","contraindications":"Elbow pain, recovery phase."}}'::jsonb),
  ('en-lowrep', 'library', 'endurance', 'inter', '{"fr":"Repeaters basse intensité","en":"Low-intensity repeaters"}'::jsonb, '{"fr":{"description":"Cycles 10 s d''effort / 5 s de repos sur grosse réglette, à 40-50 % de la charge maximale, sur 8 à 12 répétitions.","muscles":"Capacité aérobie des fléchisseurs, tolérance de charge répétée","cues":"Doit rester confortable jusqu''à la dernière répétition. Utile en phase de reprise.","errors":"Utiliser une réglette trop petite et transformer l''exercice en travail de force.","dose":"4 séries de 10 répétitions, 2 min de repos.","contraindications":"Douleur de poulie non stabilisée."},"en":{"description":"Cycles of 10 s work / 5 s rest on a large edge, at 40-50% of maximum load, for 8 to 12 reps.","muscles":"Aerobic capacity of the finger flexors, repeated-load tolerance","cues":"Should stay comfortable through the last rep. Useful in a return-to-training phase.","errors":"Using too small an edge and turning the exercise into strength work.","dose":"4 sets of 10 reps, 2 min rest.","contraindications":"Unstabilised pulley pain."}}'::jsonb),
  ('en-pyramid', 'library', 'endurance', 'all', '{"fr":"Pyramide de longueurs","en":"Lap pyramid"}'::jsonb, '{"fr":{"description":"Enchaînement croissant puis décroissant de niveaux : 5c, 6a, 6b, 6a, 5c, avec repos fixe.","muscles":"Résistance progressive, gestion de l''effort sur une séance","cues":"Le repos reste constant, seule la difficulté varie. Notez où la technique se dégrade.","errors":"Allonger le repos quand ça devient dur, ce qui masque le point de rupture.","dose":"1 pyramide complète, 4 min entre chaque longueur.","contraindications":"Aucune contre-indication majeure."},"en":{"description":"Ascending then descending grade ladder: 5c, 6a, 6b, 6a, 5c, with fixed rest.","muscles":"Progressive endurance, effort management across a session","cues":"Rest stays constant, only difficulty varies. Note where your technique degrades.","errors":"Extending rest when it gets hard, which hides your breaking point.","dose":"One complete pyramid, 4 min between laps.","contraindications":"No major contraindication."}}'::jsonb),
  ('en-6min', 'library', 'endurance', 'inter', '{"fr":"Continuité bloc 6 minutes","en":"6-minute boulder continuity"}'::jsonb, '{"fr":{"description":"Six minutes de grimpe continue sur pan, en gérant son intensité pour ne jamais tomber.","muscles":"Résistance mixte, lucidité tactique en fatigue","cues":"Repérez à l''avance vos prises de repos. Tomber avant la fin signifie une intensité mal calibrée.","errors":"Grimper sans plan et s''arrêter à la quatrième minute.","dose":"3 séries de 6 min, 6 min de repos.","contraindications":"Doigts fatigués, retour de blessure récent."},"en":{"description":"Six minutes of continuous board climbing, managing intensity to never fall.","muscles":"Mixed endurance, tactical clarity under fatigue","cues":"Identify your rest holds in advance. Falling before the end means the intensity was miscalibrated.","errors":"Climbing without a plan and stopping at the fourth minute.","dose":"3 sets of 6 min, 6 min rest.","contraindications":"Tired fingers, recent return from injury."}}'::jsonb),
  ('bd-onsight', 'library', 'equilibre', 'all', '{"fr":"Volume de blocs à vue","en":"Onsight boulder volume"}'::jsonb, '{"fr":{"description":"Enchaînement de 15 à 25 blocs faciles à modérés jamais essayés, au premier essai.","muscles":"Lecture de bloc, répertoire moteur, adaptation","cues":"Lisez le bloc depuis le sol pendant 30 s avant de partir. C''est la lecture qui progresse, pas la force.","errors":"Réessayer immédiatement après un échec : vous perdez le bénéfice du à-vue.","dose":"1 séance par semaine, 60 à 90 min.","contraindications":"Aucune."},"en":{"description":"Climbing 15 to 25 easy to moderate never-tried problems, first go.","muscles":"Problem reading, movement vocabulary, adaptability","cues":"Read the problem from the ground for 30 s before starting. What improves is the reading, not the strength.","errors":"Retrying immediately after a failure: you lose the onsight benefit.","dose":"One session per week, 60 to 90 min.","contraindications":"None."}}'::jsonb),
  ('bd-perfect', 'library', 'equilibre', 'all', '{"fr":"Répétitions parfaites","en":"Perfect repeats"}'::jsonb, '{"fr":{"description":"Répéter un bloc déjà réussi jusqu''à l''exécuter trois fois de suite sans hésitation ni ajustement.","muscles":"Automatisation motrice, économie de mouvement","cues":"L''objectif n''est pas de réussir mais de réussir identiquement. Filmez-vous pour comparer.","errors":"Changer de méthode à chaque essai.","dose":"3 blocs par séance, 3 répétitions propres chacun.","contraindications":"Aucune."},"en":{"description":"Repeating a sent problem until you execute it three times in a row with no hesitation or adjustment.","muscles":"Motor automation, movement economy","cues":"The goal is not to succeed but to succeed identically. Film yourself to compare.","errors":"Changing beta on every attempt.","dose":"3 problems per session, 3 clean repeats each.","contraindications":"None."}}'::jsonb),
  ('bd-recall', 'library', 'equilibre', 'inter', '{"fr":"Mémorisation de séquence","en":"Sequence recall"}'::jsonb, '{"fr":{"description":"Lire un bloc, puis l''exécuter sans le regarder à nouveau depuis le sol.","muscles":"Mémoire motrice, lecture, gestion du stress","cues":"Verbalisez la séquence à voix haute avant de partir. Le rappel verbal ancre la lecture.","errors":"Regarder les prises pendant la montée plutôt que d''anticiper.","dose":"5 à 8 blocs par séance.","contraindications":"Aucune."},"en":{"description":"Read a problem, then execute it without looking at it again from the ground.","muscles":"Motor memory, reading, stress management","cues":"Say the sequence aloud before starting. Verbal recall anchors the reading.","errors":"Looking at holds during the climb rather than anticipating.","dose":"5 to 8 problems per session.","contraindications":"None."}}'::jsonb),
  ('bd-steep', 'library', 'equilibre', 'inter', '{"fr":"Volume en dévers","en":"Steep volume"}'::jsonb, '{"fr":{"description":"Blocs modérés en dévers marqué, en privilégiant la tension corporelle sur la force de doigts.","muscles":"Chaîne antérieure, crochets de talon et de pointe, tension","cues":"Cherchez le placement de bassin qui allège les mains avant de tirer plus fort.","errors":"Compenser un mauvais placement par la force des bras.","dose":"1 séance par semaine, blocs 2 niveaux sous le maximum.","contraindications":"Douleur d''épaule en position haute."},"en":{"description":"Moderate problems on a steep wall, prioritising body tension over finger strength.","muscles":"Anterior chain, heel and toe hooks, tension","cues":"Look for the hip placement that unweights the hands before pulling harder.","errors":"Compensating poor positioning with arm strength.","dose":"One session per week, problems 2 grades below maximum.","contraindications":"Shoulder pain in overhead positions."}}'::jsonb),
  ('bd-slab', 'library', 'equilibre', 'all', '{"fr":"Dalle et adhérence","en":"Slab and friction"}'::jsonb, '{"fr":{"description":"Blocs de dalle exigeant équilibre, confiance dans l''adhérence et lecture des pieds.","muscles":"Chevilles, chaîne latérale, confiance et gestion du risque","cues":"Poussez sur la pointe, pas sur le talon. Le regard sur le pied jusqu''au transfert de poids complet.","errors":"Se coller au mur : en dalle, l''éloignement crée la friction.","dose":"1 séance toutes les deux semaines minimum.","contraindications":"Cheville instable, sol de réception inadapté."},"en":{"description":"Slab problems demanding balance, trust in friction and foot reading.","muscles":"Ankles, lateral chain, confidence and risk management","cues":"Push through the toe, not the heel. Eyes on the foot until weight transfer is complete.","errors":"Hugging the wall: on slab, distance creates friction.","dose":"At least one session every two weeks.","contraindications":"Unstable ankle, inadequate landing."}}'::jsonb),
  ('bd-roof', 'library', 'equilibre', 'inter', '{"fr":"Toits et crochets de talon","en":"Roofs and heel hooks"}'::jsonb, '{"fr":{"description":"Blocs de toit exigeant crochets de talon, de pointe et inversions.","muscles":"Ischio-jambiers, fessiers, abdominaux, coiffe des rotateurs","cues":"Le crochet de talon se charge progressivement. Un talon chargé brutalement en rotation est la première cause de lésion des ischio-jambiers en escalade.","errors":"Tirer violemment sur un talon mal placé.","dose":"1 séance par semaine, échauffement des ischio-jambiers obligatoire.","contraindications":"Tendinopathie proximale des ischio-jambiers."},"en":{"description":"Roof problems requiring heel hooks, toe hooks and inversions.","muscles":"Hamstrings, glutes, abdominals, rotator cuff","cues":"Load a heel hook progressively. A heel loaded abruptly in rotation is the leading cause of hamstring injury in climbing.","errors":"Yanking hard on a poorly placed heel.","dose":"One session per week, hamstring warm-up mandatory.","contraindications":"Proximal hamstring tendinopathy."}}'::jsonb),
  ('bd-onefoot', 'library', 'equilibre', 'all', '{"fr":"Grimpe à un pied","en":"One-foot climbing"}'::jsonb, '{"fr":{"description":"Grimper une voie facile en n''utilisant qu''un seul pied, l''autre restant libre.","muscles":"Équilibre, rotation de hanche, engagement du tronc","cues":"Force la rotation de bassin et le placement en lolotte sans y penser.","errors":"Choisir une voie trop dure et compenser aux bras.","dose":"2 à 3 voies par côté en échauffement.","contraindications":"Aucune."},"en":{"description":"Climbing an easy route using only one foot, the other kept free.","muscles":"Balance, hip rotation, trunk engagement","cues":"Forces hip rotation and drop-knee positioning without conscious effort.","errors":"Picking too hard a route and compensating with the arms.","dose":"2 to 3 routes per side during the warm-up.","contraindications":"None."}}'::jsonb),
  ('mb-lunge', 'library', 'mobilite', 'all', '{"fr":"Fente haute avec rotation","en":"High lunge with rotation"}'::jsonb, '{"fr":{"description":"Fente avant profonde avec rotation du tronc vers la jambe avant et bras tendu au plafond.","muscles":"Psoas, quadriceps, rotateurs thoraciques","cues":"Le bassin reste en rétroversion pour cibler le psoas plutôt que la lombaire.","errors":"Cambrer les lombaires pour paraître plus souple.","dose":"3 × 30 s par côté, en fin de séance.","contraindications":"Douleur lombaire en extension."},"en":{"description":"Deep forward lunge with trunk rotation toward the front leg and one arm reaching to the ceiling.","muscles":"Psoas, quadriceps, thoracic rotators","cues":"Keep the pelvis posteriorly tilted to target the psoas rather than the lumbar spine.","errors":"Arching the lumbar spine to look more flexible.","dose":"3 × 30 s per side, at the end of a session.","contraindications":"Lumbar pain in extension."}}'::jsonb),
  ('mb-dislocate', 'library', 'mobilite', 'all', '{"fr":"Dislocations à la barre","en":"Shoulder dislocates"}'::jsonb, '{"fr":{"description":"Passage d''un bâton ou d''un élastique de l''avant vers l''arrière, bras tendus, prise progressivement resserrée.","muscles":"Capsule antérieure de l''épaule, grand pectoral, deltoïde antérieur","cues":"Bras strictement tendus. Resserrez la prise seulement quand le passage est fluide et indolore.","errors":"Plier les coudes pour raccourcir le trajet.","dose":"2 × 10 répétitions, tous les jours en échauffement.","contraindications":"Instabilité antérieure d''épaule, luxation récente."},"en":{"description":"Passing a stick or band from front to back, arms straight, grip progressively narrowed.","muscles":"Anterior shoulder capsule, pectoralis major, anterior deltoid","cues":"Arms strictly straight. Narrow the grip only when the pass is smooth and pain-free.","errors":"Bending the elbows to shorten the path.","dose":"2 × 10 reps, daily as part of the warm-up.","contraindications":"Anterior shoulder instability, recent dislocation."}}'::jsonb),
  ('mb-erot', 'library', 'mobilite', 'all', '{"fr":"Rotation externe couchée","en":"Lying external rotation"}'::jsonb, '{"fr":{"description":"Allongé sur le dos, bras à 90° d''abduction, coude à 90°, laisser la main descendre vers le sol.","muscles":"Rotateurs internes, capsule postérieure, grand dorsal","cues":"L''omoplate reste plaquée au sol. C''est l''amplitude mesurée par le test de mobilité ALTARIS.","errors":"Décoller l''omoplate pour gagner des degrés artificiels.","dose":"3 × 45 s par côté.","contraindications":"Douleur antérieure d''épaule en fin d''amplitude."},"en":{"description":"Lying on your back, arm at 90° abduction, elbow at 90°, letting the hand lower toward the floor.","muscles":"Internal rotators, posterior capsule, latissimus dorsi","cues":"The shoulder blade stays flat on the floor. This is the range measured by the ALTARIS mobility test.","errors":"Lifting the shoulder blade to gain artificial degrees.","dose":"3 × 45 s per side.","contraindications":"Anterior shoulder pain at end range."}}'::jsonb),
  ('mb-thoracic', 'library', 'mobilite', 'all', '{"fr":"Extension thoracique","en":"Thoracic extension"}'::jsonb, '{"fr":{"description":"Extension du haut du dos sur un rouleau placé sous les omoplates, bras derrière la tête.","muscles":"Rachis thoracique, grand dorsal, chaîne antérieure","cues":"Bloquez les côtes basses en soufflant pour éviter de compenser en lombaire.","errors":"Cambrer les lombaires plutôt que d''ouvrir le thorax.","dose":"2 min par segment, avant les séances de dévers.","contraindications":"Ostéoporose, douleur costale."},"en":{"description":"Upper back extension over a foam roller placed under the shoulder blades, arms behind the head.","muscles":"Thoracic spine, latissimus dorsi, anterior chain","cues":"Lock the lower ribs by exhaling to avoid compensating through the lumbar spine.","errors":"Arching the lumbar spine instead of opening the thorax.","dose":"2 min per segment, before steep sessions.","contraindications":"Osteoporosis, rib pain."}}'::jsonb),
  ('mb-hipload', 'library', 'mobilite', 'inter', '{"fr":"Abduction de hanche chargée","en":"Loaded hip abduction"}'::jsonb, '{"fr":{"description":"Abduction active de hanche contre élastique, dans l''amplitude utile de la lolotte.","muscles":"Moyen fessier, rotateurs externes profonds","cues":"Travaillez la force dans l''amplitude gagnée. La souplesse non contrôlée ne sert pas en escalade.","errors":"Étirer sans jamais renforcer l''amplitude nouvelle.","dose":"3 × 12 par côté, 2 fois par semaine.","contraindications":"Conflit de hanche douloureux."},"en":{"description":"Active hip abduction against a band, through the range used in a drop-knee.","muscles":"Gluteus medius, deep external rotators","cues":"Build strength in the range you gained. Uncontrolled flexibility is of no use in climbing.","errors":"Stretching without ever strengthening the new range.","dose":"3 × 12 per side, twice a week.","contraindications":"Painful hip impingement."}}'::jsonb),
  ('cr-abwheel', 'library', 'gainage', 'inter', '{"fr":"Roue abdominale","en":"Ab wheel"}'::jsonb, '{"fr":{"description":"Extension antérieure contrôlée avec retour, depuis les genoux puis debout.","muscles":"Chaîne antérieure complète, grand dorsal en excentrique","cues":"Le bassin reste en rétroversion pendant toute l''amplitude. Arrêtez-vous avant que le dos ne se creuse.","errors":"Aller au maximum d''amplitude en cambrant.","dose":"3 × 8 à 12, 2 fois par semaine.","contraindications":"Lombalgie, hernie discale."},"en":{"description":"Controlled anterior extension and return, from the knees then standing.","muscles":"Full anterior chain, latissimus dorsi eccentrically","cues":"The pelvis stays posteriorly tilted throughout. Stop before the back arches.","errors":"Going to full range by arching.","dose":"3 × 8 to 12, twice a week.","contraindications":"Low back pain, disc herniation."}}'::jsonb),
  ('cr-tension', 'library', 'gainage', 'inter', '{"fr":"Tension corporelle sur pan","en":"Body tension on a steep board"}'::jsonb, '{"fr":{"description":"Mouvements lents sur pan très déversant, avec les pieds imposés sur de petites prises.","muscles":"Transfert direct de la tension vers la grimpe réelle","cues":"Le meilleur gainage pour un grimpeur reste la grimpe avec des pieds exigeants. Rien ne transfère mieux.","errors":"Remplacer entièrement le travail au mur par des abdominaux au sol.","dose":"15 min par séance de dévers.","contraindications":"Doigts fatigués."},"en":{"description":"Slow movements on a very steep board, with feet restricted to small holds.","muscles":"Direct transfer of tension to actual climbing","cues":"The best core work for a climber is still climbing with demanding footholds. Nothing transfers better.","errors":"Replacing all wall work with floor ab work.","dose":"15 min per steep session.","contraindications":"Tired fingers."}}'::jsonb),
  ('cr-pallof', 'library', 'gainage', 'all', '{"fr":"Pallof press anti-rotation","en":"Pallof press"}'::jsonb, '{"fr":{"description":"Poussée horizontale d''un élastique latéral, en résistant à la rotation du tronc.","muscles":"Obliques, transverse, stabilisateurs lombo-pelviens","cues":"Le bassin ne bouge pas d''un millimètre. La résistance à la rotation est ce qui vous garde collé au mur en dévers.","errors":"Tourner les épaules avec l''élastique.","dose":"3 × 12 par côté, tempo lent.","contraindications":"Aucune contre-indication majeure."},"en":{"description":"Horizontal press of a lateral band, resisting trunk rotation.","muscles":"Obliques, transversus, lumbopelvic stabilisers","cues":"The pelvis does not move a millimetre. Anti-rotation strength is what keeps you against the wall on steep terrain.","errors":"Turning the shoulders with the band.","dose":"3 × 12 per side, slow tempo.","contraindications":"No major contraindication."}}'::jsonb),
  ('cr-compress', 'library', 'gainage', 'inter', '{"fr":"Compression assise","en":"Seated compression"}'::jsonb, '{"fr":{"description":"Assis jambes tendues, soulever les jambes du sol en gardant le dos droit.","muscles":"Fléchisseurs de hanche en course interne, grand droit","cues":"C''est la qualité qui manque le plus souvent pour les crochets de talon hauts et les toits.","errors":"S''aider des mains en poussant fort sur le sol.","dose":"4 × 10 s de maintien.","contraindications":"Ischio-jambiers courts douloureux."},"en":{"description":"Seated with straight legs, lifting the legs off the floor while keeping the back straight.","muscles":"Hip flexors in inner range, rectus abdominis","cues":"This is the quality most often missing for high heel hooks and roofs.","errors":"Helping with the hands by pushing hard on the floor.","dose":"4 × 10 s holds.","contraindications":"Painfully short hamstrings."}}'::jsonb),
  ('ph-fingerext', 'library', 'antagonistes', 'all', '{"fr":"Extension des doigts à l''élastique","en":"Band finger extensions"}'::jsonb, '{"fr":{"description":"Ouverture des doigts contre un élastique annulaire ou dans un bac de sable.","muscles":"Extenseurs des doigts, interosseux dorsaux","cues":"Compense le déséquilibre fléchisseurs/extenseurs créé par des années de grimpe.","errors":"Aller trop vite : le mouvement doit être lent et complet.","dose":"3 × 25, tous les jours. Deux minutes bien investies.","contraindications":"Aucune."},"en":{"description":"Opening the fingers against a rubber band or in a tub of sand.","muscles":"Finger extensors, dorsal interossei","cues":"Offsets the flexor/extensor imbalance built by years of climbing.","errors":"Going too fast: the movement should be slow and complete.","dose":"3 × 25, daily. Two minutes well spent.","contraindications":"None."}}'::jsonb),
  ('ph-scap', 'library', 'antagonistes', 'all', '{"fr":"Tractions scapulaires","en":"Scapular pull-ups"}'::jsonb, '{"fr":{"description":"Depuis la suspension bras tendus, abaisser les omoplates sans plier les coudes.","muscles":"Trapèze inférieur, dentelé antérieur, grand dorsal","cues":"Amplitude minuscule, 3 à 5 cm. C''est le premier maillon de toute traction saine.","errors":"Plier les coudes et transformer l''exercice en traction.","dose":"3 × 10, en échauffement de chaque séance.","contraindications":"Aucune."},"en":{"description":"From a straight-arm hang, depress the shoulder blades without bending the elbows.","muscles":"Lower trapezius, serratus anterior, latissimus dorsi","cues":"Tiny range, 3 to 5 cm. It is the first link in any healthy pull.","errors":"Bending the elbows and turning it into a pull-up.","dose":"3 × 10, in the warm-up of every session.","contraindications":"None."}}'::jsonb),
  ('ph-pronosup', 'library', 'antagonistes', 'all', '{"fr":"Pronation-supination lestée","en":"Weighted pronation-supination"}'::jsonb, '{"fr":{"description":"Rotation lente de l''avant-bras avec un marteau ou une barre lestée d''un côté, coude fixé.","muscles":"Rond pronateur, supinateur, biceps distal","cues":"Coude collé au corps. Amplitude complète dans les deux sens, tempo 3 s.","errors":"Bouger l''épaule pour augmenter l''amplitude apparente.","dose":"3 × 12 par sens, 2 fois par semaine.","contraindications":"Douleur du biceps distal en phase aiguë."},"en":{"description":"Slow forearm rotation with a hammer or one-sided loaded bar, elbow fixed.","muscles":"Pronator teres, supinator, distal biceps","cues":"Elbow pinned to the body. Full range both ways, 3 s tempo.","errors":"Moving the shoulder to increase apparent range.","dose":"3 × 12 each way, twice a week.","contraindications":"Acute distal biceps pain."}}'::jsonb),
  ('ph-pulley', 'library', 'antagonistes', 'inter', '{"fr":"Charge progressive de poulie","en":"Progressive pulley loading"}'::jsonb, '{"fr":{"description":"Protocole de remise en charge après lésion de poulie : suspension pieds au sol, charge augmentée de 10 % par semaine.","muscles":"Poulies A2 et A4, gaine des fléchisseurs","cues":"Toujours en tendu ou demi-arqué, jamais en arqué fermé. Douleur maximale tolérée : 3/10, sans réveil nocturne.","errors":"Reprendre l''arqué fermé avant 12 semaines.","dose":"5 × 10 s, tous les 2 jours, sous supervision d''un professionnel de santé.","contraindications":"Phase aiguë (moins de 3 semaines), œdème, craquement initial audible sans avis médical."},"en":{"description":"Return-to-load protocol after a pulley injury: hang with feet down, load increased by 10% per week.","muscles":"A2 and A4 pulleys, flexor tendon sheath","cues":"Always open-hand or half-crimp, never full crimp. Maximum tolerated pain: 3/10, with no night pain.","errors":"Returning to full crimp before 12 weeks.","dose":"5 × 10 s, every 2 days, supervised by a healthcare professional.","contraindications":"Acute phase (under 3 weeks), swelling, an initial audible pop without medical review."}}'::jsonb)
